import{_ as t,c as a,o,ah as p,ao as s,ap as i}from"./chunks/framework.Dq2_gudl.js";const m=JSON.parse('{"title":"また会えるのでしょうか？ — 動物と天国について聖書が語ること","description":"ペットを失ったあとの最も深い問い。その子は天国にいるのでしょうか。ローマ書、イザヤ書、黙示録が与える希望。","frontmatter":{"title":"また会えるのでしょうか？ — 動物と天国について聖書が語ること","description":"ペットを失ったあとの最も深い問い。その子は天国にいるのでしょうか。ローマ書、イザヤ書、黙示録が与える希望。"},"headers":[],"relativePath":"ja/pets-in-heaven/will-i-see-my-pet-again.md","filePath":"ja/pets-in-heaven/will-i-see-my-pet-again.md"}'),l={name:"ja/pets-in-heaven/will-i-see-my-pet-again.md"};function n(r,e,h,c,d,g){return o(),a("div",null,[...e[0]||(e[0]=[p('<div class="pl-quote"><p>「自分が天国に行くことは分かっています。ただ知りたいのは、その子もそこで私を待っていてくれるのかどうか」</p><p class="pl-quote-soft">動物の伴侶を失った人が最もよく抱き、最も言葉にしにくい問いです。</p></div><section class="pl-section"><h2>まず正直なひとこと</h2><p>聖書は「すべてのペットは天国で飼い主と再会する」と記した一節を残していません。そう断定する人は、聖書が言っている以上のことまで言っています。</p><p>でも、だからといって絶望しないでください。聖書が描く絵は、私たちが思うよりずっと広いのです。神の贖いは「人間の魂をいくつか救い出す」ことではなく、<strong>被造物全体の新しさ</strong>です。そして動物は、その絵の初めから終わりまで、そこにいます。</p></section><section class="pl-section"><h2>1. 被造物も、私たちと一緒に待っている</h2><blockquote><p><strong>ローマ人への手紙 8:19-22</strong></p><p>&quot;For the earnest expectation of the creature waiteth for the manifestation of the sons of God… For we know that the whole creation groaneth and travaileth in pain together until now.&quot;</p></blockquote><p>パウロはここで驚くべきことを言っています。うめき、待っているのは人間だけではない。<em>被造物そのもの</em>も共にうめき、贖いを待っているのです。動物は救いの外に置き去りにされた背景ではなく、私たちと同じ結末を見つめています。</p><p>「あの子はあんなに優しかったのに、ただ消えてしまうなんておかしい」と感じるとき、あなたが感じているのは、被造物が感じていることと同じです。聖書は、その痛みは必ず応えられると語ります。</p></section><section class="pl-section"><h2>2. 神が造られる世界に、動物がいる</h2><blockquote><p><strong>イザヤ書 11:6-9</strong></p><p>&quot;The wolf also shall dwell with the lamb, and the leopard shall lie down with the kid; and the calf and the young lion and the fatling together; and a little child shall lead them.&quot;</p></blockquote><p>イザヤが見た未来は、光と雲だけの世界ではありませんでした。彼が見たのは狼、子羊、豹、子やぎ、子牛、若い獅子。互いに傷つけ合わず、安心して伏せる世界です。</p><p>もし神の動物への思いが「この世限りで、それで終わり」だったなら、約束の中に彼らの場所を用意されたはずがありません。用意されました。</p><p>そしてヨハネの黙示録は、新しい天と新しい地についてこう語ります。</p><blockquote><p><strong>ヨハネの黙示録 21:4-5</strong></p><p>&quot;And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away. …Behold, I make all things new.&quot;</p></blockquote><p>「もはや死はない」は、被造物全体への宣言です。あなたのその子が通った死も、取り除かれるもののひとつです。</p></section><section class="pl-section"><h2>3. それでは、どこまで希望を持てるのか</h2><p>希望を持てます。神はご自分が造られたものを捨てられないからです。キリストの復活が新しい創造の初穂であり、その範囲は「すべてのもの」だと聖書が言っているからです。動物を造り、動物を喜ばれた神が、突然彼らを顧みなくなったりはしないからです。</p><p>「同じあの子なのか」「私を覚えているのか」については、聖書は細部を語りません。代わりに、信頼できる神を与え、細部はその御手に委ねておられます。この沈黙は私たちを苦しめるためではなく、分からないことを良い御手に委ねるよう招いているのです。</p><p class="pl-quote-soft">よろしければ、こう祈ってみてください。</p></section><div class="pl-quote"><p>「主よ、天国の細かいことは分かりません。それでも、あなたが良い方だと信じています。<br>あなたがその子を造り、その子の一日一日を顧みてくださいました。今、私の涙も見ていてくださいます。<br>その子をあなたの御手に委ねます。自分自身を委ねるのと同じように。<br>あなたの約束にその子の場所があるなら、感謝します。<br>これから誰かがその子を世話しなければならないのなら、それがあなたでよかった。アーメン。」</p></div><section class="pl-section"><h2>とくに辛い日に</h2><p>詩篇の作者はこう書きました。「主よ、あなたは人と獣とを保存されます」（詩篇 36:6）。短い一節ですが、動物を神の保存の範囲に直接置いた、聖書でも稀なことばのひとつです。</p><p>あなたのその子は、「人と獣とを保存される」神に属しています。今日あなたに必要なのは、完全な答えではなく、このことかもしれません。その子は神の御手の中にいて、神は良い方です。</p><p><a href="/ja/pets-in-heaven/">← Pets in Heaven に戻る</a> ｜ 次の記事：<a href="/ja/pets-in-heaven/not-one-sparrow-forgotten">雀一羽さえ忘れられない</a></p></section><div class="pl-cta"><h2>その子の名前を書いてみてください。</h2><p>名前、いちばん好きだった場所、まだ言えていない言葉。PetLoss は秘密の空間です。アップロードも、急かすこともなく、ゆっくり整理するそばにいます。</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">App Store でダウンロード</a></div><div class="pl-bible"><h3>みことばが、これからも寄り添うように</h3><p>この記事の聖句はすべて聖書から引用しています。虹の聖書ウィジェットなら、いつでも聖書を読み、毎日の聖句ウィジェットを設定できます。会いたい日に、小さな灯りとなりますように。</p><div class="pl-bible-shots"><figure><img src="'+s+'" alt="虹の聖書ウィジェット — 2 テモテ 2:13" loading="lazy"><figcaption>ホーム画面に毎日の聖句</figcaption></figure><figure><img src="'+i+'" alt="虹の聖書 — 天国にいるペット トピック、マタイ 10:29-31" loading="lazy"><figcaption>「天国にいるペット」テーマで聖書を</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">App Storeで虹の聖書ウィジェットを入手</a></div>',9)])])}const u=t(l,[["render",n]]);export{m as __pageData,u as default};
